namespace
{
const char *TAG = "net";
constexpr const char *kNs = "net";
constexpr uint32_t kFallbackAfterMs = 30000;  // STA unreachable this long -> AP up
constexpr uint32_t kApOffAfterStableMs = 120000; // STA stable this long -> AP down

uint32_t now_ms()
{
    return static_cast<uint32_t>(esp_timer_get_time() / 1000);
}

std::string nvs_str(nvs_handle_t h, const char *key, const std::string &fallback = "")
{
    std::size_t len = 0;
    if (nvs_get_str(h, key, nullptr, &len) != ESP_OK || len == 0 || len > 256) {
        return fallback;
    }
    std::string out(len, '\0');
    if (nvs_get_str(h, key, &out[0], &len) != ESP_OK) {
        return fallback;
    }
    out.resize(len - 1);
    return out;
}

std::string random_password(std::size_t n)
{
    // Unambiguous alphabet (no 0/O/1/l/I) so it can be typed from a label.
    static const char alphabet[] = "abcdefghijkmnpqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ23456789";
    std::string out;
    for (std::size_t i = 0; i < n; ++i) {
        out.push_back(alphabet[esp_random() % (sizeof(alphabet) - 1)]);
    }
    return out;
}

std::string ip_str(const esp_ip4_addr_t &ip)
{
    char buf[16];
    std::snprintf(buf, sizeof(buf), IPSTR, IP2STR(&ip));
    return buf;
}

std::string mac_suffix()
{
    uint8_t mac[6] = {};
    esp_read_mac(mac, ESP_MAC_WIFI_STA);
    char buf[8];
    std::snprintf(buf, sizeof(buf), "%02x%02x", mac[4], mac[5]);
    return buf;
}
} // namespace

const char *wifi_policy_name(WifiPolicy p)
{
    switch (p) {
    case WifiPolicy::kStationOnly: return "sta_only";
    case WifiPolicy::kApOnly: return "ap_only";
    case WifiPolicy::kStationAndAp: return "sta_and_ap";
    case WifiPolicy::kStationFallbackAp: break;
    }
    return "sta_fallback_ap";
}

bool wifi_policy_from_string(const std::string &s, WifiPolicy &out)
{
    if (s == "sta_fallback_ap") out = WifiPolicy::kStationFallbackAp;
    else if (s == "sta_only") out = WifiPolicy::kStationOnly;
    else if (s == "ap_only") out = WifiPolicy::kApOnly;
    else if (s == "sta_and_ap") out = WifiPolicy::kStationAndAp;
    else return false;
    return true;
}

esp_err_t NetworkManager::load_settings()
{
    const std::string suffix = mac_suffix();
    nvs_handle_t h;
    esp_err_t err = nvs_open(kNs, NVS_READWRITE, &h);
    if (err != ESP_OK) {
        return err;
    }
    settings_.hostname = nvs_str(h, "hostname", "lumen-" + suffix);
    settings_.sta_ssid = nvs_str(h, "sta_ssid");
    settings_.sta_password = nvs_str(h, "sta_pass");
    settings_.sta_static.enabled = nvs_str(h, "st_en", "0") == "1";
    settings_.sta_static.ip = nvs_str(h, "st_ip");
    settings_.sta_static.netmask = nvs_str(h, "st_mask");
    settings_.sta_static.gateway = nvs_str(h, "st_gw");
    settings_.sta_static.dns = nvs_str(h, "st_dns");
    wifi_policy_from_string(nvs_str(h, "policy", "sta_fallback_ap"), settings_.policy);
    settings_.ap_ssid = nvs_str(h, "ap_ssid", "Lumen-" + suffix);
    settings_.ap_password = nvs_str(h, "ap_pass");
    settings_.ap_channel = static_cast<uint8_t>(std::atoi(nvs_str(h, "ap_ch", "6").c_str()));
    settings_.ethernet_enabled = nvs_str(h, "eth_en", "0") == "1";
    settings_.timezone = nvs_str(h, "tz", "UTC0");
    settings_.ntp_server = nvs_str(h, "ntp", "pool.ntp.org");
    nvs_close(h);

    bool dirty = false;
    if (settings_.ap_password.size() < 8) {
        settings_.ap_password = random_password(12); // unique per device
        dirty = true;
    }
    if (settings_.sta_ssid.empty() && std::strlen(LUMEN_DEV_WIFI_SSID) > 0) {
        settings_.sta_ssid = LUMEN_DEV_WIFI_SSID;
        settings_.sta_password = LUMEN_DEV_WIFI_PASSWORD;
        ESP_LOGW(TAG, "seeded station credentials from development build secrets");
        dirty = true;
    }
    if (settings_.ap_channel < 1 || settings_.ap_channel > 13) {
        settings_.ap_channel = 6;
    }
    return dirty ? save_settings() : ESP_OK;
}

esp_err_t NetworkManager::save_settings() const
{
    nvs_handle_t h;
    esp_err_t err = nvs_open(kNs, NVS_READWRITE, &h);
    if (err != ESP_OK) {
        return err;
    }
    nvs_set_str(h, "hostname", settings_.hostname.c_str());
    nvs_set_str(h, "sta_ssid", settings_.sta_ssid.c_str());
    nvs_set_str(h, "sta_pass", settings_.sta_password.c_str());
    nvs_set_str(h, "st_en", settings_.sta_static.enabled ? "1" : "0");
    nvs_set_str(h, "st_ip", settings_.sta_static.ip.c_str());
    nvs_set_str(h, "st_mask", settings_.sta_static.netmask.c_str());
    nvs_set_str(h, "st_gw", settings_.sta_static.gateway.c_str());
    nvs_set_str(h, "st_dns", settings_.sta_static.dns.c_str());
    nvs_set_str(h, "policy", wifi_policy_name(settings_.policy));
    nvs_set_str(h, "ap_ssid", settings_.ap_ssid.c_str());
    nvs_set_str(h, "ap_pass", settings_.ap_password.c_str());
    nvs_set_str(h, "ap_ch", std::to_string(settings_.ap_channel).c_str());
    nvs_set_str(h, "eth_en", settings_.ethernet_enabled ? "1" : "0");
    nvs_set_str(h, "tz", settings_.timezone.c_str());
    nvs_set_str(h, "ntp", settings_.ntp_server.c_str());
    err = nvs_commit(h);
    nvs_close(h);
    return err;
}

esp_err_t NetworkManager::start(const BoardProfile &profile)
{
    // Lock discipline: never hold mutex_ while calling ESP-IDF APIs that
    // register event handlers (mDNS, SNTP, Ethernet glue). The default event
    // loop holds its own lock while dispatching into handle_event(), which
    // takes mutex_ — holding both in the opposite order deadlocks.
    esp_err_t err = esp_netif_init();
    if (err != ESP_OK && err != ESP_ERR_INVALID_STATE) return err;
    err = esp_event_loop_create_default();
    if (err != ESP_OK && err != ESP_ERR_INVALID_STATE) return err;

    bool eth_declared = false;
    for (const auto &p : profile.peripherals) {
        eth_declared |= (p.type == "ethernet");
    }
    {
        std::lock_guard<std::recursive_mutex> lock(mutex_);
        err = load_settings();
        if (err != ESP_OK) {
            ESP_LOGE(TAG, "settings load failed: %s", esp_err_to_name(err));
        }
        setenv("TZ", settings_.timezone.c_str(), 1);
        tzset();
        status_.hostname = settings_.hostname;
        uint8_t mac[6] = {};
        esp_read_mac(mac, ESP_MAC_WIFI_STA);
        char macs[18];
        std::snprintf(macs, sizeof(macs), "%02x:%02x:%02x:%02x:%02x:%02x", mac[0], mac[1], mac[2],
                      mac[3], mac[4], mac[5]);
        status_.mac = macs;
        status_.eth_present = eth_declared;
    }

    sta_netif_ = esp_netif_create_default_wifi_sta();
    ap_netif_ = esp_netif_create_default_wifi_ap();
    esp_netif_set_hostname(sta_netif_, settings_.hostname.c_str());

    wifi_init_config_t cfg = WIFI_INIT_CONFIG_DEFAULT();
    err = esp_wifi_init(&cfg);
    if (err != ESP_OK) {
        ESP_LOGE(TAG, "wifi init failed: %s", esp_err_to_name(err));
        return err;
    }
    esp_wifi_set_storage(WIFI_STORAGE_RAM); // credentials are ours (NVS "net")
    esp_event_handler_register(WIFI_EVENT, ESP_EVENT_ANY_ID, &NetworkManager::on_event, this);
    esp_event_handler_register(IP_EVENT, ESP_EVENT_ANY_ID, &NetworkManager::on_event, this);

    if (eth_declared && settings_.ethernet_enabled) {
        if (start_ethernet(profile) != ESP_OK) {
            ESP_LOGW(TAG, "Ethernet init failed; continuing with Wi-Fi");
        }
    }
    {
        std::lock_guard<std::recursive_mutex> lock(mutex_);
        err = apply_wifi_mode();
    }
    start_mdns();
    start_sntp();
    ESP_LOGI(TAG, "hostname %s, policy %s, setup AP '%s' (WPA2) password: %s",
             settings_.hostname.c_str(), wifi_policy_name(settings_.policy),
             settings_.ap_ssid.c_str(), settings_.ap_password.c_str());
    return err;
}

esp_err_t NetworkManager::apply_wifi_mode()
{
    status_.sta_configured = !settings_.sta_ssid.empty();
    const bool want_sta = status_.sta_configured && settings_.policy != WifiPolicy::kApOnly;
    bool want_ap = settings_.policy == WifiPolicy::kApOnly ||
                   settings_.policy == WifiPolicy::kStationAndAp ||
                   (settings_.policy == WifiPolicy::kStationFallbackAp && !status_.sta_configured);
    if (!want_sta && !want_ap) {
        want_ap = true; // never leave the device unreachable
    }
    wifi_mode_t mode = want_sta && want_ap ? WIFI_MODE_APSTA : (want_sta ? WIFI_MODE_STA : WIFI_MODE_AP);

    if (wifi_started_) {
        esp_wifi_disconnect();
        esp_wifi_stop();
        wifi_started_ = false;
    }
    esp_err_t err = esp_wifi_set_mode(mode);
    if (err != ESP_OK) return err;

    if (want_sta) {
        wifi_config_t sta{};
        std::strncpy(reinterpret_cast<char *>(sta.sta.ssid), settings_.sta_ssid.c_str(),
                     sizeof(sta.sta.ssid));
        std::strncpy(reinterpret_cast<char *>(sta.sta.password), settings_.sta_password.c_str(),
                     sizeof(sta.sta.password));
        sta.sta.threshold.authmode =
            settings_.sta_password.empty() ? WIFI_AUTH_OPEN : WIFI_AUTH_WPA2_PSK;
        sta.sta.pmf_cfg.capable = true;
        sta.sta.scan_method = WIFI_ALL_CHANNEL_SCAN;
        sta.sta.sort_method = WIFI_CONNECT_AP_BY_SIGNAL;
        esp_wifi_set_config(WIFI_IF_STA, &sta);

        esp_netif_dhcpc_stop(sta_netif_);
        if (settings_.sta_static.enabled) {
            esp_netif_ip_info_t info{};
            info.ip.addr = ipaddr_addr(settings_.sta_static.ip.c_str());
            info.netmask.addr = ipaddr_addr(settings_.sta_static.netmask.c_str());
            info.gw.addr = ipaddr_addr(settings_.sta_static.gateway.c_str());
            esp_netif_set_ip_info(sta_netif_, &info);
            if (!settings_.sta_static.dns.empty()) {
                esp_netif_dns_info_t dns{};
                dns.ip.u_addr.ip4.addr = ipaddr_addr(settings_.sta_static.dns.c_str());
                dns.ip.type = ESP_IPADDR_TYPE_V4;
                esp_netif_set_dns_info(sta_netif_, ESP_NETIF_DNS_MAIN, &dns);
            }
        } else {
            esp_netif_dhcpc_start(sta_netif_);
        }
    }
    if (want_ap) {
        wifi_config_t ap{};
        std::strncpy(reinterpret_cast<char *>(ap.ap.ssid), settings_.ap_ssid.c_str(),
                     sizeof(ap.ap.ssid));
        ap.ap.ssid_len = static_cast<uint8_t>(settings_.ap_ssid.size());
        std::strncpy(reinterpret_cast<char *>(ap.ap.password), settings_.ap_password.c_str(),
                     sizeof(ap.ap.password));
        ap.ap.channel = settings_.ap_channel;
        ap.ap.max_connection = 4;
        ap.ap.authmode = WIFI_AUTH_WPA2_PSK; // never open (SPEC §15.2)
        ap.ap.pmf_cfg.capable = true;
        esp_wifi_set_config(WIFI_IF_AP, &ap);
    }
    ap_on_ = want_ap;
    status_.ap_active = want_ap;
    status_.ap_ssid = settings_.ap_ssid;
    status_.ap_ip = want_ap ? "192.168.4.1" : "";
    err = esp_wifi_start();
    if (err == ESP_OK) {
        wifi_started_ = true;
        esp_wifi_set_ps(WIFI_PS_MIN_MODEM);
        if (want_sta) {
            sta_down_since_ms_ = now_ms();
            esp_wifi_connect();
        }
    }
    return err;
}

void NetworkManager::start_ap_locked(bool on)
{
    if (on == ap_on_) return;
    wifi_mode_t mode = WIFI_MODE_STA;
    esp_wifi_get_mode(&mode);
    if (on) {
        wifi_config_t ap{};
        std::strncpy(reinterpret_cast<char *>(ap.ap.ssid), settings_.ap_ssid.c_str(), sizeof(ap.ap.ssid));
        ap.ap.ssid_len = static_cast<uint8_t>(settings_.ap_ssid.size());
        std::strncpy(reinterpret_cast<char *>(ap.ap.password), settings_.ap_password.c_str(),
                     sizeof(ap.ap.password));
        ap.ap.channel = settings_.ap_channel;
        ap.ap.max_connection = 4;
        ap.ap.authmode = WIFI_AUTH_WPA2_PSK;
        esp_wifi_set_mode(WIFI_MODE_APSTA);
        esp_wifi_set_config(WIFI_IF_AP, &ap);
        ESP_LOGW(TAG, "station unreachable: fallback AP '%s' enabled", settings_.ap_ssid.c_str());
    } else {
        esp_wifi_set_mode(WIFI_MODE_STA);
        ESP_LOGI(TAG, "station stable: fallback AP disabled");
    }
    ap_on_ = on;
    status_.ap_active = on;
    status_.ap_ip = on ? "192.168.4.1" : "";
}

void NetworkManager::poll()
{
    std::lock_guard<std::recursive_mutex> lock(mutex_);
    const uint32_t now = now_ms();
    if (wifi_started_ && status_.sta_configured && settings_.policy != WifiPolicy::kApOnly) {
        if (!status_.sta_connected && next_retry_ms_ != 0 && now >= next_retry_ms_) {
            next_retry_ms_ = 0;
            esp_wifi_connect();
        }
        if (settings_.policy == WifiPolicy::kStationFallbackAp) {
            if (!status_.sta_connected && !ap_on_ && now - sta_down_since_ms_ > kFallbackAfterMs) {
                start_ap_locked(true);
                notify();
            } else if (status_.sta_connected && ap_on_ && status_.ap_clients == 0 &&
                       now - sta_up_since_ms_ > kApOffAfterStableMs) {
                start_ap_locked(false);
                notify();
            }
        }
        if (status_.sta_connected) {
            wifi_ap_record_t info{};
            if (esp_wifi_sta_get_ap_info(&info) == ESP_OK) {
                status_.rssi = info.rssi;
            }
        }
    }
    status_.time_synced = std::time(nullptr) > 1700000000;
}

void NetworkManager::on_event(void *arg, esp_event_base_t base, int32_t id, void *data)
{
    static_cast<NetworkManager *>(arg)->handle_event(base, id, data);
}

void NetworkManager::handle_event(esp_event_base_t base, int32_t id, void *data)
{
    std::lock_guard<std::recursive_mutex> lock(mutex_);
    const uint32_t now = now_ms();
    if (base == WIFI_EVENT) {
        switch (id) {
        case WIFI_EVENT_STA_DISCONNECTED: {
            const bool was_up = status_.sta_connected;
            status_.sta_connected = false;
            status_.sta_ip.clear();
            if (was_up) {
                sta_down_since_ms_ = now;
                retry_delay_ms_ = 1000;
                ESP_LOGW(TAG, "station disconnected");
                notify();
            }
            status_.sta_reconnects++;
            next_retry_ms_ = now + retry_delay_ms_;
            retry_delay_ms_ = retry_delay_ms_ < 30000 ? retry_delay_ms_ * 2 : 30000;
            break;
        }
        case WIFI_EVENT_AP_STACONNECTED:
            status_.ap_clients++;
            notify();
            break;
        case WIFI_EVENT_AP_STADISCONNECTED:
            if (status_.ap_clients > 0) status_.ap_clients--;
            notify();
            break;
        default:
            break;
        }
    } else if (base == IP_EVENT) {
        if (id == IP_EVENT_STA_GOT_IP) {
            auto *ev = static_cast<ip_event_got_ip_t *>(data);
            status_.sta_connected = true;
            status_.sta_ssid = settings_.sta_ssid;
            status_.sta_ip = ip_str(ev->ip_info.ip);
            status_.sta_gateway = ip_str(ev->ip_info.gw);
            status_.sta_netmask = ip_str(ev->ip_info.netmask);
            sta_up_since_ms_ = now;
            retry_delay_ms_ = 1000;
            esp_netif_sntp_start(); // (re)sync the clock right away (schedules depend on it)
            ESP_LOGI(TAG, "station connected to '%s', IP %s — open http://%s/ or http://%s.local/",
                     settings_.sta_ssid.c_str(), status_.sta_ip.c_str(), status_.sta_ip.c_str(),
                     settings_.hostname.c_str());
            notify();
        } else if (id == IP_EVENT_ETH_GOT_IP) {
            auto *ev = static_cast<ip_event_got_ip_t *>(data);
            status_.eth_ip = ip_str(ev->ip_info.ip);
            status_.eth_link = true;
            ESP_LOGI(TAG, "Ethernet IP %s", status_.eth_ip.c_str());
            notify();
        } else if (id == IP_EVENT_STA_LOST_IP) {
            status_.sta_ip.clear();
        }
    } else if (base == ETH_EVENT) {
        if (id == ETHERNET_EVENT_CONNECTED) {
            status_.eth_link = true;
            ESP_LOGI(TAG, "Ethernet link up");
        } else if (id == ETHERNET_EVENT_DISCONNECTED) {
            status_.eth_link = false;
            status_.eth_ip.clear();
            ESP_LOGW(TAG, "Ethernet link down");
        }
        notify();
    }
}

esp_err_t NetworkManager::start_ethernet(const BoardProfile &profile)
{
#if !SOC_EMAC_SUPPORTED
    (void)profile;
    return ESP_ERR_NOT_SUPPORTED; // no internal EMAC on this SoC
#else
    const BoardPeripheral *eth = nullptr;
    for (const auto &p : profile.peripherals) {
        if (p.type == "ethernet") eth = &p;
    }
    const BoardResource *res = nullptr;
    for (const auto &r : profile.resources) {
        if (eth != nullptr && r.id == eth->bus) res = &r;
    }
    if (eth == nullptr || res == nullptr) {
        return ESP_ERR_NOT_FOUND;
    }
    int phy_addr = 0;
    std::string clock_mode = "gpio17_out";
    if (!eth->settings_json.empty()) {
        cJSON *s = cJSON_Parse(eth->settings_json.c_str());
        if (s != nullptr) {
            const cJSON *a = cJSON_GetObjectItemCaseSensitive(s, "phy_address");
            if (cJSON_IsNumber(a)) phy_addr = a->valueint;
            const cJSON *c = cJSON_GetObjectItemCaseSensitive(s, "clock_mode");
            if (cJSON_IsString(c)) clock_mode = c->valuestring;
            cJSON_Delete(s);
        }
    }
    eth_esp32_emac_config_t emac = ETH_ESP32_EMAC_DEFAULT_CONFIG();
    emac.smi_gpio.mdc_num = res->pin("mdc");
    emac.smi_gpio.mdio_num = res->pin("mdio");
    const int clk = res->pin("clk");
    if (clock_mode.rfind("gpio", 0) == 0 && clock_mode.find("_out") != std::string::npos) {
        emac.clock_config.rmii.clock_mode = EMAC_CLK_OUT;
        emac.clock_config.rmii.clock_gpio = clk;
    } else {
        emac.clock_config.rmii.clock_mode = EMAC_CLK_EXT_IN;
        emac.clock_config.rmii.clock_gpio = clk >= 0 ? clk : 0;
    }
    eth_mac_config_t mac_cfg = ETH_MAC_DEFAULT_CONFIG();
    eth_phy_config_t phy_cfg = ETH_PHY_DEFAULT_CONFIG();
    phy_cfg.phy_addr = phy_addr;
    phy_cfg.reset_gpio_num = res->pin("power");
    esp_eth_mac_t *mac = esp_eth_mac_new_esp32(&emac, &mac_cfg);
    esp_eth_phy_t *phy = mac ? esp_eth_phy_new_generic(&phy_cfg) : nullptr;
    if (mac == nullptr || phy == nullptr) {
        return ESP_FAIL;
    }
    esp_eth_config_t cfg = ETH_DEFAULT_CONFIG(mac, phy);
    esp_eth_handle_t handle = nullptr;
    esp_err_t err = esp_eth_driver_install(&cfg, &handle);
    if (err != ESP_OK) {
        return err;
    }
    esp_netif_config_t ncfg = ESP_NETIF_DEFAULT_ETH();
    eth_netif_ = esp_netif_new(&ncfg);
    esp_netif_set_hostname(eth_netif_, settings_.hostname.c_str());
    esp_netif_attach(eth_netif_, esp_eth_new_netif_glue(handle));
    esp_event_handler_register(ETH_EVENT, ESP_EVENT_ANY_ID, &NetworkManager::on_event, this);
    eth_handle_ = handle;
    err = esp_eth_start(handle);
    ESP_LOGI(TAG, "Ethernet started (phy addr %d, mdc %d, mdio %d, clk %d %s): %s", phy_addr,
             emac.smi_gpio.mdc_num, emac.smi_gpio.mdio_num, clk, clock_mode.c_str(),
             esp_err_to_name(err));
    return err;
#endif
}

void NetworkManager::start_mdns()
{
    if (mdns_started_) {
        mdns_hostname_set(settings_.hostname.c_str());
        return;
    }
    if (mdns_init() != ESP_OK) {
        return;
    }
    mdns_hostname_set(settings_.hostname.c_str());
    mdns_instance_name_set("Lumen lighting controller");
    mdns_service_add(nullptr, "_http", "_tcp", 80, nullptr, 0);
    mdns_txt_item_t txt[] = {{"api", "/api/v1"}};
    mdns_service_add(nullptr, "_lumen", "_tcp", 80, txt, 1);
    mdns_started_ = true;
}

void NetworkManager::start_sntp()
{
    esp_sntp_config_t cfg = ESP_NETIF_SNTP_DEFAULT_CONFIG(settings_.ntp_server.c_str());
    cfg.start = true;
    esp_netif_sntp_init(&cfg);
}

void NetworkManager::notify()
{
    if (listener_ != nullptr) {
        listener_(listener_user_);
    }
}

NetworkStatus NetworkManager::status() const
{
    std::lock_guard<std::recursive_mutex> lock(mutex_);
    return status_;
}

NetworkSettings NetworkManager::settings() const
{
    std::lock_guard<std::recursive_mutex> lock(mutex_);
    return settings_;
}

esp_err_t NetworkManager::update_wifi(const std::string &ssid, const std::string *password,
                                      const StaticIpConfig &static_ip)
{
    std::lock_guard<std::recursive_mutex> lock(mutex_);
    if (ssid.size() > 32 || (password != nullptr && password->size() > 63) ||
        (password != nullptr && !password->empty() && password->size() < 8)) {
        return ESP_ERR_INVALID_ARG;
    }
    if (static_ip.enabled && (ipaddr_addr(static_ip.ip.c_str()) == IPADDR_NONE ||
                              ipaddr_addr(static_ip.netmask.c_str()) == IPADDR_NONE ||
                              ipaddr_addr(static_ip.gateway.c_str()) == IPADDR_NONE)) {
        return ESP_ERR_INVALID_ARG;
    }
    settings_.sta_ssid = ssid;
    if (password != nullptr) settings_.sta_password = *password;
    settings_.sta_static = static_ip;
    esp_err_t err = save_settings();
    if (err == ESP_OK) {
        err = apply_wifi_mode();
    }
    notify();
    return err;
}

esp_err_t NetworkManager::update_ap(const std::string *ssid, const std::string *password,
                                    WifiPolicy policy, uint8_t channel)
{
    std::lock_guard<std::recursive_mutex> lock(mutex_);
    if ((ssid != nullptr && (ssid->empty() || ssid->size() > 32)) ||
        (password != nullptr && (password->size() < 8 || password->size() > 63)) ||
        channel < 1 || channel > 13) {
        return ESP_ERR_INVALID_ARG;
    }
    if (ssid != nullptr) settings_.ap_ssid = *ssid;
    if (password != nullptr) settings_.ap_password = *password;
    settings_.policy = policy;
    settings_.ap_channel = channel;
    esp_err_t err = save_settings();
    if (err == ESP_OK) err = apply_wifi_mode();
    notify();
    return err;
}

esp_err_t NetworkManager::update_system(const std::string *hostname, const std::string *timezone,
                                        const std::string *ntp_server, const bool *ethernet_enabled)
{
    std::lock_guard<std::recursive_mutex> lock(mutex_);
    if (hostname != nullptr) {
        if (hostname->empty() || hostname->size() > 31) return ESP_ERR_INVALID_ARG;
        for (char c : *hostname) {
            if (!((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-')) return ESP_ERR_INVALID_ARG;
        }
        settings_.hostname = *hostname;
        status_.hostname = *hostname;
        esp_netif_set_hostname(sta_netif_, hostname->c_str());
        mdns_hostname_set(hostname->c_str());
    }
    if (timezone != nullptr) {
        if (timezone->empty() || timezone->size() > 48) return ESP_ERR_INVALID_ARG;
        settings_.timezone = *timezone;
        setenv("TZ", timezone->c_str(), 1);
        tzset();
    }
    if (ntp_server != nullptr) {
        if (ntp_server->empty() || ntp_server->size() > 63) return ESP_ERR_INVALID_ARG;
        settings_.ntp_server = *ntp_server;
    }
    if (ethernet_enabled != nullptr) {
        settings_.ethernet_enabled = *ethernet_enabled; // takes effect after restart
    }
    return save_settings();
}

std::string NetworkManager::scan_json()
{
    wifi_scan_config_t cfg{};
    cfg.show_hidden = false;
    std::string out = "[]";
    if (esp_wifi_scan_start(&cfg, true) != ESP_OK) {
        return out;
    }
    uint16_t n = 20;
    wifi_ap_record_t recs[20];
    if (esp_wifi_scan_get_ap_records(&n, recs) != ESP_OK) {
        return out;
    }
    cJSON *arr = cJSON_CreateArray();
    for (uint16_t i = 0; i < n; ++i) {
        if (recs[i].ssid[0] == 0) continue;
        cJSON *o = cJSON_CreateObject();
        cJSON_AddStringToObject(o, "ssid", reinterpret_cast<const char *>(recs[i].ssid));
        cJSON_AddNumberToObject(o, "rssi", recs[i].rssi);
        cJSON_AddNumberToObject(o, "channel", recs[i].primary);
        cJSON_AddBoolToObject(o, "secure", recs[i].authmode != WIFI_AUTH_OPEN);
        cJSON_AddItemToArray(arr, o);
    }
    char *text = cJSON_PrintUnformatted(arr);
    cJSON_Delete(arr);
    if (text != nullptr) {
        out = text;
        cJSON_free(text);
    }
    return out;
}

